import json,glob,re,collections,os
levels=collections.Counter(); services=collections.Counter(); bad=[]
for f in glob.glob('logs/*'):
    for i,l in enumerate(open(f),1):
        l=l.rstrip('\n')
        if f.endswith('.jsonl'):
            try:
                o=json.loads(l); levels[o.get('level')]+=1; services[o.get('service')]+=1
                if set(o)!={'ts','level','service','msg'}: bad.append((f,i,o))
            except Exception as e: bad.append((f,i,str(e),l))
        else:
            m=re.match(r'^(\S+) (\S+) +\[([^]]+)\] (.*)$',l)
            if m:
                levels[m.group(2)]+=1; services[m.group(3)]+=1
            else: bad.append((f,i,l))
print('levels',levels)
print('services',services)
print('bad count',len(bad))
for x in bad[:30]: print(x)
PY"}

