{"command": "python3 - <<'PY'
import json,glob,re,collections
err=collections.Counter(); users=collections.Counter(); dbt=[]; over=0; reqs=0
for f in sorted(glob.glob('logs/*')):
    for i,l in enumerate(open(f),1):
        if f.endswith('.jsonl'):
            o=json.loads(l); ts=o['ts']; lvl=o['level']; svc=o['service']; msg=o['msg']
        else:
            m=re.match(r'^(\S+) (\S+) +\[([^]]+)\] (.*)$',l.rstrip('\n'))
            ts,lvl,svc,msg=m.groups()
        if lvl=='ERROR': err[svc]+=1
        if svc=='auth' and lvl=='WARN' and 'login failed' in msg:
            # extract user
            mm=re.search(r'\buser=(\S+)',msg)
            if mm: users[mm.group(1)]+=1
            else: print('NOUSER',f,i,msg)
        if 'db timeout' in msg.lower():
            dbt.append((ts,lvl,svc,msg,f,i))
        if 'request done' in msg:
            reqs+=1
            mm=re.search(r'\blatency_ms=(\d+)',msg)
            if mm and int(mm.group(1))>2000: over+=1
            elif not mm: print('NOLAT',f,i,msg)
print('error_counts',dict(err))
print('users',users, 'top', users.most_common())
print('db timeouts',len(dbt))
for x in dbt: print(x)
print('requests',reqs,'over',over)
PY"}

